-- Restrict match chat to its two participants and ARQON organizers.
-- The chat room key is generated by the frontend from the two player names,
-- not from drafts.data.match_id.

drop policy if exists messages_public_read on public.messages;
drop policy if exists messages_participant_insert on public.messages;

create policy messages_match_participant_read
on public.messages
for select
to authenticated
using (
  public.has_organizer_role('editor')
  or exists (
    select 1
    from public.drafts d
    where (
      messages.match_id = coalesce(d.data->>'p1_name','') || '_vs_' || coalesce(d.data->>'p2_name','')
      or messages.match_id = coalesce(d.data->>'p2_name','') || '_vs_' || coalesce(d.data->>'p1_name','')
    )
    and (
      (d.data->>'p1_uid') = (select auth.uid())::text
      or (d.data->>'p2_uid') = (select auth.uid())::text
    )
  )
);

create policy messages_participant_insert
on public.messages
for insert
to authenticated
with check (
  length(btrim(coalesce(text, ''))) between 1 and 1000
  and length(btrim(coalesce(sender, ''))) between 1 and 80
  and (
    public.has_organizer_role('editor')
    or (
      exists (
        select 1
        from public.players p
        where p.uid = (select auth.uid())::text
          and p.name = messages.sender
      )
      and exists (
        select 1
        from public.drafts d
        where (
          messages.match_id = coalesce(d.data->>'p1_name','') || '_vs_' || coalesce(d.data->>'p2_name','')
          or messages.match_id = coalesce(d.data->>'p2_name','') || '_vs_' || coalesce(d.data->>'p1_name','')
        )
        and (
          (d.data->>'p1_uid') = (select auth.uid())::text
          or (d.data->>'p2_uid') = (select auth.uid())::text
        )
      )
    )
  )
);
